// ─── SUBSCRIPTION & PLANS : freemium | trial_premium | earned_premium | premium ──
const TRIAL_DAYS      = 15;   // alias backward compat
const TRIAL_BASE_DAYS = 15;   // jours trial automatique à l'inscription
const TRIAL_MAX_DAYS  = 30;   // plafond absolu depuis la date de création du compte
const FILLEUL_BONUS_DAYS = 15; // jours "Premium – x j restants" offerts au filleul validé
const REF_TRIAL_PALIERS = { 1: 5, 2: 10 }; // bonus parrain phase trial (3+ = 0j)
const PREM_BONUS_PER_REF = 1;  // jours/filleul validé phase premium abonné
const PREM_MAX_PER_MONTH = 5;  // plafond jours bonus/mois premium
const SPIN_PER_REF = 1;        // tours de roue par filleul validé (tous statuts)
function makeRefCode(id,email){ const b=(email||"").split("@")[0].replace(/[^a-z0-9]/gi,"").toUpperCase().slice(0,4).padEnd(4,"X"); return `DUV-${b}-${String(id).slice(-4).padStart(4,"0")}`; }
function makeSub() { return { plan:"trial_premium", accountCreatedAt:new Date().toISOString(), trialStart:new Date().toISOString(), premiumSince:null, cycle:"yearly", refCode:null, refUsed:null, refCount:0, validatedRefCount:0, refMonths:0, trialExtension:0, pendingSpins:0, monthlyRefMonth:null, monthlyRefCount:0 }; }
function refBonusDaysTrial(validatedCount, extSoFar) {
  const remaining = TRIAL_MAX_DAYS - TRIAL_BASE_DAYS - extSoFar;
  if(remaining <= 0) return 0;
  const palier = REF_TRIAL_PALIERS[validatedCount] ?? 0;
  return Math.min(palier, remaining);
}
function refBonusDaysPremium(monthlyCount) {
  return monthlyCount <= PREM_MAX_PER_MONTH ? PREM_BONUS_PER_REF : 0;
}
// backward compat
function refBonusDays(n) { return REF_TRIAL_PALIERS[n] ?? 0; }
function refBonusDaysFor(n, isPF) { return isPF ? refBonusDaysPremium(n) : refBonusDaysTrial(n, 0); }
function makeAdminSub() { return { plan:"premium", premiumSince:new Date().toISOString(), cycle:"yearly", earnedTheme:true, earnedBadge:true, earnedRG:true, earnedWC:true, earnedVideo:true, earnedLicorne:true, giftedPrizes:{}, _admin:true }; }
function subStatus(sub) {
  if(sub._admin) return "premium";
  if(sub.plan==="premium") {
    // Vérifie l'expiration de l'abonnement payant
    if(sub.premiumSince && sub.cycle) {
      const expiry = new Date(sub.premiumSince);
      sub.cycle==="yearly" ? expiry.setFullYear(expiry.getFullYear()+1) : expiry.setMonth(expiry.getMonth()+1);
      const bonusDays = sub.refMonths ? sub.refMonths * 30 : 0;
      expiry.setDate(expiry.getDate() + bonusDays);
      if(Date.now() > expiry.getTime()) return "freemium"; // abonnement expiré → freemium
    }
    return "premium";
  }
  // 🔒 Override admin "Bêta" par compte (date de fin propre à CE compte,
  // distincte de la bascule bêta globale ci-dessous). Tant que non dépassée :
  // accès complet (identique à un trial). Une fois dépassée : redevient un
  // Trial Premium normal de 15 jours qui démarre à CETTE date de fin — calculé
  // à la volée à chaque appel, jamais réécrit en base.
  if(sub.plan==="beta") {
    const betaEndMs = sub.betaEnd ? new Date(sub.betaEnd).getTime() : 0;
    if(Date.now() < betaEndMs) return "trial_premium";
    const d = (Date.now()-betaEndMs)/86400000;
    return d<=TRIAL_BASE_DAYS ? "trial_premium" : "freemium";
  }
  // 🔒 sub.plan==="freemium" ne peut JAMAIS être organique — makeSub() démarre
  // toujours en "trial_premium" ; "freemium" n'existe que forcé explicitement
  // (panneau admin AccountSubscriptionCard, ou debug local). Doit donc primer
  // sur la bêta globale ci-dessous, sinon impossible de tester le rendu
  // Freemium pendant une période de bêta globale active.
  if(sub.plan==="freemium") return "freemium";
  const created = sub.accountCreatedAt || sub.trialStart;
  const ext = sub.trialExtension||0;
  const maxDays = Math.min(TRIAL_BASE_DAYS + ext, TRIAL_MAX_DAYS);
  const d = (Date.now()-new Date(created).getTime())/86400000;
  if(d<=maxDays) return sub.plan==="earned_premium" ? "earned_premium" : "trial_premium";
  if(isBeta()) return "trial_premium"; // 🎉 Bêta globale — Trial Premium offert à tous, une fois le trial (forcé ou organique) réellement épuisé
  return "freemium"; // expiré → freemium
}
function trialLeft(sub) { const created=sub.accountCreatedAt||sub.trialStart; const ext=sub.trialExtension||0; const maxDays=Math.min(TRIAL_BASE_DAYS+ext,TRIAL_MAX_DAYS); return Math.max(0,Math.ceil(maxDays-(Date.now()-new Date(created).getTime())/86400000)); }
function isPrem(sub) { const st=subStatus(sub); return st==="premium"||st==="trial_premium"||st==="earned_premium"||sub._admin; }
function isFreemiumPlan(sub) { return subStatus(sub)==="freemium"; }
function getPerms(sub) {
  const st=subStatus(sub);
  const isFree    = st==="freemium";
  const isTrial   = st==="trial_premium"||st==="earned_premium"; // inclut la bêta
  const isPremium = st==="premium"||sub._admin;
  return {
    maxParents:    2,
    maxChildren:   isFree?1:isTrial?2:5,
    sameGuardAll:  !isFree,
    zoneChoice:    !isFree,
    feteMere:      !isFree,
    fetePere:      !isFree,
    birthParents:  !isFree,
    birthChildren: !isFree,
    customDates:   !isFree,
    maxCustomDates:isPremium?Infinity:isTrial?2:0,
    customGuard:   !isFree,
    weatherEnabled: !isFree,
    messagingEnabled: !isFree,
    obsCanGuardEnabled: !isFree,
    maxObservers:  isFree?0:isTrial?2:5,
    calendarEdit:  true,
    scheduleAdd:   !isFree,
    expenseAdd:    true,
    refundAdd:     true,
    balanceVisible:!isFree,
    contactAdd:    !isFree,
    maxVaultDocs:  (isPremium||isTrial) ? Infinity : 0,   // Coffre-fort : Premium + Bêta/trial
    maxStorageMB:   isPremium ? 200 : isTrial ? 50 : 0,   // Stockage total : Premium 200 Mo · Trial 50 Mo · Freemium 0 Mo
    maxVaultSizeGB: isPremium ? 200/1024 : isTrial ? 50/1024 : 0, // dérivé de maxStorageMB
    canSpin:       !isFree,
    spinWinSub:    isPremium,
  };
}
// Rang d'un plan pour comparaison : freemium < trial/earned/bêta < premium.
// Utilisé uniquement pour choisir le "meilleur" des deux plans parents.
function planRankFor(sub) {
  const s = subStatus(sub);
  if (s === "premium") return 2;
  if (s === "trial_premium" || s === "earned_premium") return 1;
  return 0; // freemium
}

// À partir des lignes brutes renvoyées par get_family_billing_context()
// (une par parent actif), calcule le quota d'observateurs de la famille en
// retenant le MEILLEUR des deux plans parents — décision produit explicite
// (voir docs/superpowers/specs/2026-07-14-observer-quota-enforcement-design.md).
// Aucun parent trouvé (cas défensif, ne devrait pas arriver) → repli sur 1,
// jamais Infinity par défaut (le plus restrictif réel, 0 en Freemium, n'a de
// sens que si on sait vraiment que la famille est Freemium — ici on ne sait
// rien du tout, donc on ne verrouille pas plus qu'un compte Trial fraîchement créé).
//
// 🔧 Après la review du Task 1, la RPC fait désormais un LEFT JOIN vers
// subscriptions : un parent actif peut donc arriver ici avec parent_plan
// NULL (pas encore de ligne — l'upsert client est débounce de 3s). On ne
// veut PAS que ce cas se traduise par subStatus() en "freemium" par défaut
// (Date invalide → comparaison NaN → false → repli sur freemium) : ce serait
// le sens d'erreur le plus dommageable (verrouiller à tort un observateur
// d'une famille déjà payante juste parce que la synchro n'a pas eu le temps
// de se faire). On traite donc un parent sans ligne comme un compte tout
// juste créé en Trial (le défaut réel de makeSub() pour tout nouveau compte).
// bestParentSub : réduit les lignes brutes de get_family_billing_context() au
// "meilleur des deux plans parents" de la famille — réutilisé à la fois par
// familyMaxObservers() (quota d'observateurs, inchangé) et par le statut
// effectif partagé par toute la famille (voir l'effet checkFamilyBilling et
// effectiveSub plus bas dans App()). Un parent sans encore de ligne
// subscriptions (upsert client-side avec 3s de debounce) est traité comme un
// Trial fraîchement créé, jamais comme Freemium par défaut (voir le
// commentaire détaillé ci-dessus sur le LEFT JOIN de la RPC).
function bestParentSub(parentRows) {
  if (!parentRows || parentRows.length === 0) return null;
  const subs = parentRows.map(r => r.parent_plan ? {
    plan: r.parent_plan,
    premiumSince: r.parent_premium_since,
    cycle: r.parent_cycle,
    trialStart: r.parent_trial_start,
    trialExtension: r.parent_trial_extension_days,
    accountCreatedAt: r.parent_account_created_at,
    betaEnd: r.parent_beta_end,
    parentUserId: r.parent_user_id || null,
    aiEnabled: !!r.parent_ai_enabled,
  } : {
    plan: "trial_premium",
    accountCreatedAt: new Date().toISOString(),
    trialStart: new Date().toISOString(),
    trialExtension: 0,
    parentUserId: null,
    aiEnabled: false,
  });
  const best = subs.reduce((acc, s) => planRankFor(s) > planRankFor(acc) ? s : acc, subs[0]);
  // 🔧 (2026-07-27) L'IA est un add-on indépendant du rang de plan (voir le
  // commentaire sur isPremiumAi plus bas dans ce fichier) : si N'IMPORTE LEQUEL
  // des deux parents l'a, toute la famille en bénéficie — même règle "toujours
  // le plus haut" que pour le plan de base, mais évaluée séparément (peut être
  // vraie même quand le plan "gagnant" ci-dessus n'est pas celui du parent qui
  // a l'IA). Bug corrigé : un co-parent héritant du plan Premium d'un parent
  // Premium+IA restait bloqué sans accès IA car ce flag n'était jamais propagé.
  return { ...best, aiEnabled: subs.some(s => s.aiEnabled) };
}
function familyMaxObservers(parentRows) {
  const best = bestParentSub(parentRows);
  return best ? getPerms(best).maxObservers : 1;
}
function isAdmin(user) { return user?.role==="admin"; }

// ─── BÊTA GRATUITE — pilotée depuis Supabase (table app_config), plus une
// constante codée en dur. _globalBetaCache est rempli une seule fois par un
// effet dans App() (voir plus bas) ; isBeta() le lit directement, exactement
// comme il lisait BETA_END avant — même rôle de constante partagée, juste
// chargée depuis la base pour être pilotable sans redéploiement de code.
let _globalBetaCache = { enabled: false, endMs: null };
// Âge du consentement numérique (RGPD art. 8) — le socle UE est 16 ans, sauf
// dérogation nationale abaissant le seuil (minimum légal autorisé : 13 ans).
// En dessous du seuil applicable, le consentement d'un titulaire de
// l'autorité parentale est requis.
// ⚠️ Valeurs issues de la documentation publique des transpositions RGPD par
// pays — à faire valider par un juriste avant de s'y fier en production.
const RGPD_CONSENT_AGE_BY_COUNTRY = {
  FR:15, BE:13, CH:16, LU:16, DE:16, AT:14, NL:16,
  ES:14, PT:13, IT:14, GB:13, PL:16, CZ:15, SK:16, HR:16, CA:13,
};
const RGPD_CONSENT_AGE_DEFAULT = 16; // socle RGPD par défaut si pays inconnu
function rgpdConsentAge(country) {
  return RGPD_CONSENT_AGE_BY_COUNTRY[country] ?? RGPD_CONSENT_AGE_DEFAULT;
}
function isBeta() { return _globalBetaCache.enabled && Date.now() < (_globalBetaCache.endMs ?? 0); }

