// Returns the default subdivision code for a country (first in list)
function getDefaultSub(country) {
  const subs = OH_SUBS_CATALOG[country];
  return subs?.[0]?.code || null;
}

// Returns whether a country has multiple zones to choose from
function hasMultipleZones(country) {
  return (OH_SUBS_CATALOG[country]?.length || 0) > 1;
}

// In-memory cache: key → { schoolHols, publicHols, ts }
const OH_CACHE = {};
function ohCacheKey(country, zone, year) { return `${country}|${zone||""}|${year}`; }

// In-memory cache: key "lat|lon" → tableau de prévisions {date,code,tempMax,tempMin}.
// Toujours les coordonnées DE L'UTILISATEUR CONNECTÉ lui-même (getMyLocation()) —
// jamais celles d'un autre membre de la famille, donc pas de souci de
// confidentialité à fetcher Open-Meteo directement depuis le client ici.
const MY_WEATHER_CACHE = {};
async function fetchMyWeatherForecast(lat, lon) {
  const key = `${Number(lat).toFixed(2)}|${Number(lon).toFixed(2)}`;
  if (MY_WEATHER_CACHE[key]) return MY_WEATHER_CACHE[key];
  // 🔧 hourly demandé dans la MÊME requête que daily (une seule requête,
  // pas d'appel Open-Meteo supplémentaire) — alimente le popup météo
  // détaillée matin/après-midi/soir (clic sur un jour de la bande).
  const url = `https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&daily=weathercode,temperature_2m_max,temperature_2m_min&hourly=weathercode,temperature_2m,precipitation_probability&timezone=auto&forecast_days=16`;
  const res = await fetch(url);
  if (!res.ok) throw new Error("weather fetch failed");
  const data = await res.json();
  const hourlyTimes = data?.hourly?.time || [];
  const days = (data?.daily?.time || []).map((dateStr, idx) => {
    const dayHours = [];
    hourlyTimes.forEach((t, hIdx) => {
      if (!t.startsWith(dateStr)) return;
      dayHours.push({
        hour: Number(t.slice(11, 13)),
        code: data.hourly.weathercode[hIdx],
        temp: data.hourly.temperature_2m[hIdx],
        rainChance: data.hourly.precipitation_probability[hIdx],
      });
    });
    return {
      date: dateStr,
      code: data.daily.weathercode[idx],
      tempMax: data.daily.temperature_2m_max[idx],
      tempMin: data.daily.temperature_2m_min[idx],
      periods: dayHours.length > 0 ? aggregateHourlyPeriods(dayHours) : null,
    };
  });
  MY_WEATHER_CACHE[key] = days;
  return days;
}

// Open-Meteo n'a pas d'endpoint de reverse-geocoding (coordonnées → nom de
// ville) — Nominatim (OpenStreetMap) est le seul service gratuit sans clé
// pour ça. Usage ponctuel (un clic utilisateur), donc dans les clous de leur
// politique d'usage (pas de bulk, User-Agent identifiable requis).
async function reverseGeocodeCity(lat, lon) {
  const url = `https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${lat}&lon=${lon}&zoom=10&addressdetails=1`;
  const res = await fetch(url, { headers: { "Accept-Language": "fr" } });
  if (!res.ok) throw new Error("reverse geocode failed");
  const data = await res.json();
  const a = data?.address || {};
  const city = a.city || a.town || a.village || a.municipality || a.county;
  if (!city) throw new Error("no city in reverse geocode result");
  return a.country ? `${city}, ${a.country}` : city;
}

async function fetchOHSchoolHols(country, zone, year) {
  // zone is a full subdivisionCode e.g. "FR-IDF", "DE-BY"
  const sub = zone || getDefaultSub(country);
  if (!sub) return null;
  try {
    const url = `${OH_BASE}/SchoolHolidays?countryIsoCode=${country}&subdivisionCode=${sub}&validFrom=${year}-01-01&validTo=${year+1}-12-31&languageIsoCode=FR`;
    const res = await fetch(url);
    if (!res.ok) return null;
    const data = await res.json();
    return (data||[]).map(h => ({
      n: (h.name||[]).find(x=>x.language==="FR")?.text || (h.name||[])[0]?.text || h.id,
      s: h.startDate.slice(0,10),
      e: h.endDate.slice(0,10),
    }));
  } catch { return null; }
}

async function fetchOHPublicHols(country, year) {
  if (!COUNTRIES.find(c=>c.code===country)?.ohCode) return null;
  try {
    const url = `${OH_BASE}/PublicHolidays?countryIsoCode=${country}&validFrom=${year}-01-01&validTo=${year}-12-31&languageIsoCode=FR`;
    const res = await fetch(url);
    if (!res.ok) return null;
    const data = await res.json();
    return (data||[]).map(h => ({
      date: h.startDate.slice(0,10),
      n: (h.name||[]).find(x=>x.language==="FR")?.text || (h.name||[])[0]?.text || h.id,
    }));
  } catch { return null; }
}

async function fetchOHData(country, zone, year) {
  const key = ohCacheKey(country, zone, year);
  if (OH_CACHE[key]) return OH_CACHE[key];
  const [schoolHols, publicHols] = await Promise.all([
    fetchOHSchoolHols(country, zone, year),
    fetchOHPublicHols(country, year),
  ]);
  const result = { schoolHols, publicHols, ts: Date.now() };
  OH_CACHE[key] = result;
  return result;
}

