// ─── EMOJI CROSS-PLATEFORME (Twemoji) ─────────────────────────────────────────
// 🔧 Direction "moderne mais douce" (branche staging) : les emoji natifs
// rendent différemment selon l'OS (Windows/Android/iOS ont chacune leur
// propre police d'emoji) — Twemoji fige le même rendu (image SVG) partout,
// et corrige au passage un bug réel : `color:"#fff"` sur un emoji natif ne
// fait jamais rien (un emoji est une image multicolore, pas un glyphe texte
// qui respecte le CSS `color`) — voir le bouton d'appel "urgence" dans
// ContactsTab, qui essayait ça sans effet. Avec `invert`, un twemoji peut
// enfin être rendu blanc pour de vrai (filter CSS, marche sur une image).
// Portée de cette 1ère passe : icônes les plus visibles/répétées (barre
// d'onglets, boutons du header, bouton d'appel urgence) — pas une conversion
// exhaustive des emoji dans les 18k lignes du fichier.
// 🔧 Le paquet npm "twemoji" (v14+) ne contient plus que le JS de parsing —
// Twitter a retiré les images SVG du dépôt principal (archivé depuis). On
// pointe vers jdecked/twemoji, le fork communautaire activement maintenu qui
// continue de publier les assets, épinglé à une version précise (pas
// "@latest") pour ne pas revivre ce même genre de rupture silencieuse.
// 🔧 L'emoji 📅 (calendrier) est une image FIXE dans Twemoji (et la plupart
// des jeux d'emoji) : elle affiche en dur "JUL 17", peu importe la vraie
// date du jour — vérifié en inspectant l'asset SVG lui-même. Utilisé comme
// icône de l'onglet Calendrier, ça affichait donc une fausse date à
// l'année longue. Ce composant reproduit le même style visuel (bandeau
// rouge + numéro du jour) mais avec la vraie date courante.
function CalendarDateIcon({size="1.15em", lang="fr"}) {
  const now = new Date();
  const month = now.toLocaleDateString(lang, {month:"short"}).replace(".","").toUpperCase();
  const day = now.getDate();
  // 🔧 Dimensionné en em (comme <Emoji size="1.15em">) plutôt qu'en px fixes :
  // ça reprend exactement le même contexte de taille/alignement que les
  // icônes emoji voisines dans la barre d'onglets (fontSize du bouton actif
  // vs inactif), au lieu d'une taille figée qui ne matchait ni leur taille
  // ni leur centrage vertical dans le bouton flex.
  return (
    <span style={{display:"inline-flex",flexDirection:"column",fontSize:size,width:"1em",height:"1em",borderRadius:"22%",overflow:"hidden",boxShadow:"0 1px 2px rgba(0,0,0,.25)",lineHeight:1,userSelect:"none",flexShrink:0}}>
      <span style={{background:"#DD2F45",color:"#fff",fontSize:"0.28em",fontWeight:800,textAlign:"center",padding:"0.06em 0",letterSpacing:"-.03em"}}>{month}</span>
      <span style={{flex:1,background:"#F5F8FA",color:"#66757F",fontSize:"0.5em",fontWeight:800,display:"flex",alignItems:"center",justifyContent:"center"}}>{day}</span>
    </span>
  );
}
const TWEMOJI_CDN = "https://cdn.jsdelivr.net/gh/jdecked/twemoji@17.0.3/assets/svg/";
function Emoji({children, size, invert=false, style}) {
  if (typeof children !== "string" || !children) return children;
  const cp = twemoji.convert.toCodePoint(children);
  // 🔧 jdecked/twemoji omet le fichier avec le sélecteur de variation U+FE0F
  // pour certains emoji à UN SEUL codepoint (ex: 🗄️ "1f5c4-fe0f" → 404 réel,
  // "1f5c4" seul existe) — mais le GARDE pour d'autres séquences ZWJ (ex:
  // 👱‍♀️ "1f471-200d-2640-fe0f", 👩‍⚕️ "1f469-200d-2695-fe0f" → 200, sans
  // le fe0f → 404). Un retrait systématique (essayé une première fois) cassait
  // donc ces derniers. On tente d'abord le code tel quel, et on ne retire le
  // -fe0f qu'en repli, seulement si l'image échoue vraiment à charger.
  const cpNoVS = cp.replace(/-fe0f$/, "");
  return (
    <img
      src={`${TWEMOJI_CDN}${cp}.svg`}
      onError={e => {
        if (cpNoVS !== cp) { e.currentTarget.onerror = null; e.currentTarget.src = `${TWEMOJI_CDN}${cpNoVS}.svg`; }
      }}
      alt={children}
      draggable={false}
      style={{
        height: size || "1em",
        width: size || "1em",
        display: "inline-block",
        verticalAlign: "-0.15em",
        filter: invert ? "brightness(0) invert(1)" : undefined,
        ...style,
      }}
    />
  );
}

// ─── AVATARS ──────────────────────────────────────────────────────────────────
const PARENT_AVATARS = ["👩","👨","👩‍🦱","👨‍🦱","👩‍🦰","👨‍🦰","👩‍🦳","👨‍🦳","👩‍🦲","👨‍🦲","🧔","👱‍♀️","👱","🧑","👮‍♀️","👮","👩‍⚕️","👨‍⚕️","👩‍🏫","👨‍🏫","🧕","🧑‍🦱","🧑‍🦰","🧑‍🦳"];
// Réactions emoji sur les messages — jeu fixe volontairement limité (pas de
// sélecteur libre), voir docs/superpowers/specs/2026-07-07-message-reactions-design.md
const MSG_REACTION_EMOJIS = ["👍","❤️","😂","😮","😢","🙏"];
// 🔧 Pas de variantes "cheveux" (👧‍🦱 etc.) : Unicode ne définit ces séquences
// ZWJ que pour les emoji adultes (👨/👩/🧑 + cheveux) — jamais pour 👧/👦.
// Ce ne sont pas de vrais emoji : aucune police (Twemoji ou autre) n'a
// jamais eu d'asset pour ces combinaisons, d'où les icônes cassées.
const CHILD_AVATARS  = ["🧒","👧","👦","🧑‍🎨","🧑‍🎤","🧑‍🚀","🧑‍💻","👼","🧸","🦄","🐣","⭐"];
const OBS_AVATARS    = ["👴","👵","🧓","👩‍👦","👨‍👦","👩‍👧","👨‍👧","🧑‍🤝‍🧑","👫","👬","👭","🤶","🎅","🧙‍♀️","🧙","🧝‍♀️","🦸‍♀️","🦸","🤴","👸"];

function Avatar({emoji, color, size=40, onClick, selected=false}) {
  const isPhoto = typeof emoji === "string" && emoji.startsWith("http");
  return (
    <div onClick={onClick} style={{
      width:size, height:size, borderRadius:"50%",
      background:color?`${color}22`:"#f0f1f6",
      border:`2.5px solid ${selected?color||"#7c6fcd":"transparent"}`,
      display:"flex", alignItems:"center", justifyContent:"center",
      fontSize:size*0.5, cursor:onClick?"pointer":"default",
      boxShadow:selected?`0 0 0 3px ${color||"#7c6fcd"}44`:"none",
      transition:"all .15s", flexShrink:0,
      userSelect:"none", overflow:"hidden",
    }}>
      {isPhoto
        ? <img src={emoji} alt="" style={{width:"100%",height:"100%",objectFit:"cover",borderRadius:"50%"}} />
        : <Emoji size={`${size*0.5}px`}>{emoji}</Emoji>}
    </div>
  );
}

// ─── CROP MODAL (zoom + recadrage photo) ──────────────────────────────────────
function CropModal({ file, onCrop, onCancel }) {
  const {C,t} = useApp();
  const canvasRef = useRef(null);
  const [img, setImg] = useState(null);
  const [zoom, setZoom] = useState(1);
  const [offset, setOffset] = useState({x:0, y:0});
  const dragging = useRef(false);
  const lastPos = useRef({x:0, y:0});
  const SIZE = 240;

  useEffect(() => {
    if (!file) return;
    const i = new Image();
    i.onload = () => setImg(i);
    i.src = URL.createObjectURL(file);
    return () => URL.revokeObjectURL(i.src);
  }, [file]);

  useEffect(() => {
    if (!img || !canvasRef.current) return;
    const ctx = canvasRef.current.getContext("2d");
    ctx.clearRect(0, 0, SIZE, SIZE);
    // Dessiner un cercle de clip
    ctx.save();
    ctx.beginPath();
    ctx.arc(SIZE/2, SIZE/2, SIZE/2, 0, Math.PI*2);
    ctx.clip();
    // Calculer la taille de l'image zoomée
    const scale = zoom * Math.max(SIZE/img.width, SIZE/img.height);
    const w = img.width * scale;
    const h = img.height * scale;
    const x = (SIZE - w) / 2 + offset.x;
    const y = (SIZE - h) / 2 + offset.y;
    ctx.drawImage(img, x, y, w, h);
    ctx.restore();
    // Bordure du cercle
    ctx.beginPath();
    ctx.arc(SIZE/2, SIZE/2, SIZE/2 - 1, 0, Math.PI*2);
    ctx.strokeStyle = C.vio;
    ctx.lineWidth = 2;
    ctx.stroke();
  }, [img, zoom, offset, C.vio]);

  function clampOffset(ox, oy, z) {
    if (!img) return {x:ox, y:oy};
    const scale = z * Math.max(SIZE/img.width, SIZE/img.height);
    const w = img.width * scale;
    const h = img.height * scale;
    const maxX = Math.max(0, (w - SIZE) / 2);
    const maxY = Math.max(0, (h - SIZE) / 2);
    return {x: Math.max(-maxX, Math.min(maxX, ox)), y: Math.max(-maxY, Math.min(maxY, oy))};
  }

  function handlePointerDown(e) {
    dragging.current = true;
    lastPos.current = {x: e.clientX, y: e.clientY};
    e.target.setPointerCapture(e.pointerId);
  }
  function handlePointerMove(e) {
    if (!dragging.current) return;
    const dx = e.clientX - lastPos.current.x;
    const dy = e.clientY - lastPos.current.y;
    setOffset(o => clampOffset(o.x + dx, o.y + dy, zoom));
    lastPos.current = {x: e.clientX, y: e.clientY};
  }
  function handlePointerUp() { dragging.current = false; }

  function handleZoom(newZoom) {
    setZoom(newZoom);
    setOffset(o => clampOffset(o.x, o.y, newZoom));
  }

  function handleCrop() {
    if (!canvasRef.current) return;
    canvasRef.current.toBlob(blob => { if (blob) onCrop(blob); }, "image/jpeg", 0.85);
  }

  if (!file) return null;
  return (
    <div style={{position:"fixed",inset:0,zIndex:9999,background:"rgba(0,0,0,.3)",backdropFilter:"blur(2px)",WebkitBackdropFilter:"blur(2px)",display:"flex",alignItems:"center",justifyContent:"center"}}>
      <div style={{background:C.card,borderRadius:20,padding:20,maxWidth:320,width:"90%",textAlign:"center"}}>
        <div style={{fontWeight:800,fontSize:14,marginBottom:12,color:C.txt}}>📷 {t.cropPhotoTitle||"Recadrer la photo"}</div>
        <canvas ref={canvasRef} width={SIZE} height={SIZE}
          onPointerDown={handlePointerDown} onPointerMove={handlePointerMove} onPointerUp={handlePointerUp}
          style={{width:SIZE,height:SIZE,borderRadius:"50%",cursor:"grab",touchAction:"none",display:"block",margin:"0 auto"}} />
        <div style={{marginTop:14,display:"flex",alignItems:"center",gap:8,justifyContent:"center"}}>
          <span style={{fontSize:12}}>🔍</span>
          <input type="range" min="1" max="3" step="0.05" value={zoom} onChange={e=>handleZoom(+e.target.value)}
            style={{flex:1,maxWidth:180,accentColor:C.vio}} />
          <span style={{fontSize:10,color:C.mut}}>{Math.round(zoom*100)}%</span>
        </div>
        <div style={{marginTop:14,display:"flex",gap:10,justifyContent:"center"}}>
          <button onClick={onCancel} style={{padding:"8px 20px",borderRadius:10,border:`1.5px solid ${C.bor}`,background:C.sur,color:C.txt,fontSize:13,fontWeight:600,cursor:"pointer"}}>{t.cropCancel||"Annuler"}</button>
          <button onClick={handleCrop} style={{padding:"8px 20px",borderRadius:10,border:"none",background:`linear-gradient(135deg,${C.vio},${C.pin})`,color:"#fff",fontSize:13,fontWeight:700,cursor:"pointer"}}>✓ {t.cropConfirm||"Valider"}</button>
        </div>
      </div>
    </div>
  );
}

function ParentCityField({isMine, C, t, familyId, onLocationChange}) {
  const [location, setLocation] = useState(null);
  const [loading, setLoading] = useState(true);
  const [query, setQuery] = useState("");
  const [results, setResults] = useState([]);
  const [searching, setSearching] = useState(false);
  const [locating, setLocating] = useState(false);
  const [showSearch, setShowSearch] = useState(false);

  useEffect(() => {
    if (!isMine) return;
    getMyLocation().then(loc => { setLocation(loc); setLoading(false); }).catch(() => setLoading(false));
  }, [isMine]);

  if (!isMine) return null; // 🔒 jamais affiché pour un autre parent — voir spec vie privée

  async function save(city, lat, lon) {
    try {
      await setMyLocation(familyId, city, lat, lon);
      setLocation({ city, lat, lon });
      onLocationChange?.({ city, lat, lon });
    } catch (e) {
      console.error("[Duvia] setMyLocation error:", e);
    }
  }

  async function doSearch() {
    const q = query.trim();
    if (!q) return;
    setSearching(true);
    setResults([]);
    try {
      const res = await fetch(`https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(q)}&count=5&language=fr`);
      const data = await res.json();
      setResults(data?.results || []);
    } catch {
      setResults([]);
    } finally {
      setSearching(false);
    }
  }

  function pick(r) {
    const label = [r.name, r.admin1, r.country].filter(Boolean).join(", ");
    save(label, r.latitude, r.longitude);
    setShowSearch(false); setQuery(""); setResults([]);
  }

  function useMyLocation() {
    if (!navigator.geolocation) return;
    setLocating(true);
    navigator.geolocation.getCurrentPosition(
      async (pos) => {
        const { latitude, longitude } = pos.coords;
        let city;
        try {
          city = await reverseGeocodeCity(latitude, longitude);
        } catch {
          city = t.myLocation||"📍 Ma position";
        }
        await save(city, latitude, longitude);
        setLocating(false);
      },
      () => { setLocating(false); },
      { timeout: 10000 }
    );
  }

  if (loading) return null;

  return (
    <div>
      <div style={{display:"flex",alignItems:"center",gap:8,flexWrap:"wrap"}}>
        <button type="button" onClick={useMyLocation} disabled={locating} title={t.useMyLocation||"Utiliser ma position"} aria-label={t.useMyLocation||"Utiliser ma position"}
          style={{height:26,width:26,padding:0,background:C.sur,border:`1.5px solid ${C.bor}`,borderRadius:"50%",fontSize:13,color:C.txt,cursor:locating?"wait":"pointer",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
          {locating ? "…" : "📍"}
        </button>
        <button type="button" onClick={()=>setShowSearch(v=>!v)} title={t.searchCity||"Rechercher"} aria-label={t.searchCity||"Rechercher"}
          style={{height:26,width:26,padding:0,background:C.sur,border:`1.5px solid ${C.bor}`,borderRadius:"50%",fontSize:13,color:C.txt,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
          🔍
        </button>
        <div style={{fontSize:13,color:location?.city?C.txt:C.mut}}>{location?.city || (t.noCitySet||"Non renseignée")}</div>
      </div>
      {showSearch && (
        <div style={{marginTop:8}}>
          <div style={{display:"flex",gap:6}}>
            <input value={query} onChange={e=>setQuery(e.target.value)} onKeyDown={e=>e.key==="Enter"&&doSearch()}
              placeholder={t.cityPlaceholder||"Nom de la ville"}
              style={{flex:1,height:32,padding:"0 10px",borderRadius:8,border:`1.5px solid ${C.bor}`,background:C.inp,color:C.txt,fontSize:12,boxSizing:"border-box"}} />
            <button type="button" onClick={doSearch} disabled={searching}
              style={{height:32,padding:"0 12px",borderRadius:8,border:"none",background:C.vio,color:"#fff",fontSize:12,fontWeight:700,cursor:searching?"wait":"pointer"}}>
              {searching ? "…" : (t.searchBtn||"OK")}
            </button>
          </div>
          {results.length > 0 && (
            <div style={{marginTop:6,display:"flex",flexDirection:"column",gap:4}}>
              {results.map((r,idx)=>(
                <button key={idx} type="button" onClick={()=>pick(r)}
                  style={{textAlign:"left",padding:"6px 10px",borderRadius:8,border:`1px solid ${C.bor}`,background:C.card,color:C.txt,fontSize:12,cursor:"pointer"}}>
                  {[r.name, r.admin1, r.country].filter(Boolean).join(", ")}
                </button>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

function AvatarPicker({current, onSelect, pool, color}) {
  const [open, setOpen] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [cropFile, setCropFile] = useState(null);
  const fileRef = useRef(null);
  const {C,t,myUid} = useApp();
  const swatch = color||C.vio;

  function handleFileSelect(e) {
    const file = e.target.files?.[0];
    if (!file) return;
    if (file.size > 5 * 1024 * 1024) { alert(t.avatarTooLarge||"Photo trop lourde (max 5 Mo)"); return; }
    if (!file.type.startsWith("image/")) { alert(t.avatarFileNotSupported||"Fichier non supporté"); return; }
    setCropFile(file);
    if (fileRef.current) fileRef.current.value = "";
  }

  async function handleCroppedBlob(blob) {
    if (!myUid) return;
    setUploading(true);
    setCropFile(null);
    try {
      const path = `${myUid}/${Date.now()}.jpg`;
      const { error } = await supabase.storage.from("avatars").upload(path, blob, { upsert: true, contentType: "image/jpeg" });
      if (error) throw error;
      const { data } = supabase.storage.from("avatars").getPublicUrl(path);
      if (data?.publicUrl) { onSelect(data.publicUrl); setOpen(false); }
    } catch (err) {
      console.error("[Duvia] Avatar upload error:", err);
      alert(t.avatarUploadError||"Erreur lors de l'upload de la photo");
    } finally {
      setUploading(false);
    }
  }

  return (
    <div style={{position:"relative",zIndex:open?500:1}}>
      <Avatar emoji={current||pool[0]} color={color} size={44} onClick={()=>setOpen(o=>!o)} selected={!!current} />
      {open && (
        <>
          <div onClick={()=>setOpen(false)} style={{position:"fixed",inset:0,zIndex:498}} />
          <div style={{position:"absolute",top:50,left:0,zIndex:499,background:C.card,border:`1.5px solid ${C.bor}`,borderRadius:14,padding:8,boxShadow:"0 8px 24px rgba(0,0,0,.25)",display:"grid",gridTemplateColumns:"repeat(5,44px)",gap:4,width:"auto"}}>
            {pool.map((em,i)=>(
              <div key={i} onClick={()=>{onSelect(em);setOpen(false);}} style={{
                width:40,height:40,borderRadius:8,display:"flex",alignItems:"center",justifyContent:"center",
                cursor:"pointer",background:current===em?`${swatch}22`:"transparent",
                border:`1.5px solid ${current===em?swatch:"transparent"}`,
                transition:"all .1s",flexShrink:0,overflow:"hidden",
              }}><Emoji size="22px">{em}</Emoji></div>
            ))}
            {/* Bouton galerie photo */}
            <div onClick={()=>!uploading && fileRef.current?.click()} style={{
              width:40,height:40,borderRadius:8,display:"flex",alignItems:"center",justifyContent:"center",
              fontSize:uploading?14:20,cursor:uploading?"wait":"pointer",
              background:typeof current==="string"&&current.startsWith("http")?`${swatch}22`:"transparent",
              border:`1.5px solid ${typeof current==="string"&&current.startsWith("http")?swatch:C.bor}`,
              transition:"all .1s",flexShrink:0,
            }}>{uploading?"⏳":"🖼️"}</div>
            {/* Bouton appareil photo (mobile) */}
            <div onClick={()=>{if(!uploading){const inp=document.createElement("input");inp.type="file";inp.accept="image/*";inp.capture="user";inp.onchange=e=>handleFileSelect(e);inp.click();}}} style={{
              width:40,height:40,borderRadius:8,display:"flex",alignItems:"center",justifyContent:"center",
              fontSize:20,cursor:uploading?"wait":"pointer",
              background:"transparent",
              border:`1.5px solid ${C.bor}`,
              transition:"all .1s",flexShrink:0,
            }}>📷</div>
            <input ref={fileRef} type="file" accept="image/*" onChange={handleFileSelect} style={{display:"none"}} />
          </div>
        </>
      )}
      {cropFile && <CropModal file={cropFile} onCrop={handleCroppedBlob} onCancel={()=>setCropFile(null)} />}
    </div>
  );
}

